]
keys = ("Rule","Why","When not to","Pitfall","Support")
for f in files:
    old = subprocess.check_output(["git","show",f"HEAD:{f}"], text=True)
    new = open(f).read()
    def body(t, strip_bullet):
        out=[]
        for l in t.splitlines():
            s = l[2:] if strip_bullet and l.startswith("- ") else l
            if any(s.startswith(f"**{k}:**") for k in keys):
                out.append(s)
        return out
    ob, nb = body(old, False), body(new, True)
    print(f)
    print("  rule-body lines:", len(ob), "->", len(nb), "identical" if ob == nb else "DIFF")
    if ob != nb:
        import difflib
        for line in difflib.unified_diff(ob, nb, lineterm="", n=0):
            if line.startswith(("+","-")) and not line.startswith(("+++","---")):
                print("   ", line[:160])
    def urls(t):
        return re.findall(r'\*\*See also:\*\*.*?(https?://[^\s)]+)', t)
    ou, nu = urls(old), urls(new)
    print("  see-also urls:", len(ou), "->", len(nu), "identical" if ou==nu else "DIFF")
    if ou != nu:
        print("   OLD:", ou); print("   NEW:", nu)
